set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"00000000-0000-0000-0000-000000000001","role":"authenticated","user_metadata":{"role":"admin"}}',true);
select pg_temp.assert_true(current_user='authenticated' and not (select rolbypassrls from pg_roles where rolname=current_user), 'tests run without bypass RLS');
select pg_temp.assert_true((select count(*)=1 from public.profiles), 'learner sees own private profile only');
select pg_temp.assert_true((select count(*)=1 and min(lesson_id)='equations' from public.lesson_progress), 'learner cannot read another progress record');
select pg_temp.assert_true((select count(*)=1 from public.assessment_attempts), 'attempt answers are private');
select pg_temp.assert_true((select count(*)=1 from public.learner_bookmarks), 'bookmarks are private');
select pg_temp.assert_true((select count(*)=1 and bool_and(role='learner') from public.user_roles), 'user metadata does not assign app roles');
select pg_temp.expect_error($q$insert into public.user_roles(user_id,role) values ('00000000-0000-0000-0000-000000000001','admin')$q$,'42501','no self-promotion to admin');
select pg_temp.expect_error($q$update public.user_roles set role='champion'$q$,'42501','no promotion to champion');
select pg_temp.expect_error($q$insert into public.tutor_profiles(user_id,academic_grade) values ('00000000-0000-0000-0000-000000000001',12)$q$,'42501','cannot self-provision tutor');
select pg_temp.expect_error($q$update public.tutor_profiles set teaching_skill_score=100$q$,'42501','cannot tamper with Teaching Skill Score');
select pg_temp.expect_error($q$update public.lesson_progress set checkpoint_percent=100$q$,'42501','clients cannot manufacture mastery');
select pg_temp.expect_error($q$insert into public.assessment_attempts(learner_id,assessment_id,lesson_id,selected_option,score_percent) values ('00000000-0000-0000-0000-000000000001','equations-checkpoint','equations',0,100)$q$,'42501','scores require a trusted service');
select pg_temp.expect_error($q$insert into public.learner_bookmarks(learner_id,lesson_id) values ('00000000-0000-0000-0000-000000000002','equations')$q$,'42501','cross-user bookmark insert denied');
select pg_temp.expect_error($q$update public.profiles set id='00000000-0000-0000-0000-000000000002'$q$,'42501','profile ownership cannot be reassigned');
update public.profiles set display_name='Learner local test' where id='00000000-0000-0000-0000-000000000002';
select pg_temp.assert_true((select count(*)=0 from public.profiles where display_name='Learner local test'), 'cross-user profile update affects no row');
update public.profiles set display_name='Own display name' where id=auth.uid();
select pg_temp.assert_true((select display_name='Own display name' from public.profiles where id=auth.uid()), 'safe own-profile update works');
insert into public.learner_bookmarks(learner_id,lesson_id) values (auth.uid(),'water') on conflict do nothing;
insert into public.learner_bookmarks(learner_id,lesson_id) values (auth.uid(),'water') on conflict do nothing;
select pg_temp.assert_true((select count(*)=1 from public.learner_bookmarks where lesson_id='water'), 'repeated own bookmark is idempotent');
delete from public.learner_bookmarks where learner_id='00000000-0000-0000-0000-000000000002';
select pg_temp.assert_true((select count(*)=2 from public.learner_bookmarks), 'cross-user bookmark deletion affects no visible row');
select public.switch_learner_enrollment('cbse-8-mathematics','English');
select pg_temp.expect_error($q$insert into public.learner_academic_enrollments(learner_id,subject_id,language,is_active) values (auth.uid(),'cbse-6-mathematics','English',true)$q$,'42501','direct insert cannot bypass atomic switching');
select pg_temp.expect_error($q$insert into public.learner_academic_enrollments(learner_id,subject_id,language) values ('00000000-0000-0000-0000-000000000002','cbse-8-mathematics','English')$q$,'42501','cannot enroll another learner');
reset role;
